def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str):
        return None

    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path
        if path == '':
            path = '/'

    link_count = 0
    components = path.split('/')
    queue = list(reversed(components))
    result = []  # stack of path segments (without slashes)

    while queue:
        comp = queue.pop()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if result:
                result.pop()
        else:
            result.append(comp)
            current = '/' + '/'.join(result)
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[current]
                if not target.startswith('/'):
                    parent = '/' + '/'.join(result[:-1])
                    if parent == '/':
                        target = '/' + target
                    else:
                        target = parent + '/' + target
                result.pop()  # remove the link name itself; replaced by target resolution
                target_components = target.split('/')
                queue.extend(reversed(target_components))

    if not result:
        return '/'
    return '/' + '/'.join(result)

